
window.__YGO_TARGET_BUILD='Alpha 1263';
/* Alpha1027 first-render network gate: defer optional remote fetches until DOM is ready.
   Embedded catalog/rules stay available synchronously; user-triggered fetches after boot run normally. */
(()=>{try{
 const W=window,F=typeof W.fetch==='function'?W.fetch.bind(W):null;if(!F||W.__YGO1023_FETCH_GATE)return;
 const Q=[];let open=false;W.__YGO1023_FETCH_GATE={queue:Q,nativeFetch:F,get open(){return open}};
 W.fetch=(...args)=>open?F(...args):new Promise((resolve,reject)=>Q.push({args,resolve,reject,at:Date.now()}));
 const flush=()=>{if(open)return;open=true;const rows=Q.splice(0);for(const j of rows)F(...j.args).then(j.resolve,j.reject);try{W.__YGO1023_FETCH_GATE.flushed=rows.length;W.__YGO1023_FETCH_GATE.openedAt=Date.now()}catch(_){}};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(flush,60),{once:true});else setTimeout(flush,0);
 setTimeout(flush,1500);
}catch(_){}})();
const C=[
["CONSISTENCIA","Capacidad de realizar la estrategia principal de forma estable.","✧"],
["POTENCIA OFENSIVA","Capacidad de generar presión, daño y condiciones de victoria.","⚔"],
["RESILIENCIA","Capacidad de recuperarse ante interrupciones y pérdida de recursos.","✦"],
["CONTROL DEL CAMPO","Capacidad de mantener y manipular el campo a tu favor.","◉"],
["COMIENZO DEL DUELO","Fuerza en los primeros turnos y capacidad de establecer la jugada inicial.","⚡"],
["MITAD DEL DUELO","Capacidad de mantener ventaja, recursos y control durante la partida.","◇"],
["FINAL DEL DUELO","Capacidad de cerrar partidas o mantenerse fuerte en duelos largos.","✹"],
["INTERACCIÓN","Capacidad de responder al rival mediante interrupciones, negaciones y respuestas.","✦"],
["PODER DE ATRACCIÓN","Capacidad de generar acceso adicional a cartas mediante robo, búsqueda y efectos que aumentan las opciones disponibles.","⬡"],
["VERSATILIDAD","Capacidad de adaptarse a diferentes situaciones y líneas de juego.","♢"]];
const STAT_ICON_DATA=['data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/png;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,']; let v=Array(10).fill(0),fmt="TCG";

function makeStats(){
 const host=document.getElementById("stats"),sl=document.getElementById("sliders");host.innerHTML="";sl.innerHTML="";
 C.forEach((c,i)=>{
  host.insertAdjacentHTML("beforeend",`<div class="stat"><div class="ico"><img src="${STAT_ICON_DATA[i]}" alt="" /></div><div><div class="nm">${c[0]}</div><div class="ds">${c[1]}</div></div><div class="sv" id="sv${i}">${v[i]}/10</div><div class="bar"><i id="br${i}" style="width:${v[i]*10}%"></i></div></div>`);
  sl.insertAdjacentHTML("beforeend",`<div class="points-row"><b>${c[0]}</b><div class="point-control" id="pc${i}" data-index="${i}" role="slider" tabindex="0" aria-label="${c[0]}" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${v[i]}">${Array.from({length:10},(_,p)=>`<button type="button" class="point ${p<v[i]?"active":""}" data-value="${p+1}" aria-label="${p+1} puntos"></button>`).join("")}</div><b class="points-value" id="rv${i}">${v[i]}/10</b></div>`);
  const pc=document.getElementById("pc"+i);
  const setPointValue=(val)=>{v[i]=Math.max(0,Math.min(10,Math.round(val)));pc.querySelectorAll(".point").forEach((p,k)=>p.classList.toggle("active",k<v[i]));pc.setAttribute("aria-valuenow",v[i]);document.getElementById("rv"+i).textContent=v[i]+"/10";document.getElementById("sv"+i).textContent=v[i]+"/10";document.getElementById("br"+i).style.width=(v[i]*10)+"%";window.calculate?.()};
  pc.querySelectorAll(".point").forEach(p=>p.addEventListener("pointerdown",e=>{e.preventDefault();pc.setPointerCapture?.(e.pointerId);setPointValue(+p.dataset.value)}));
  pc.addEventListener("pointermove",e=>{if(e.buttons===0)return;const r=pc.getBoundingClientRect(),step=r.width/10;setPointValue(Math.ceil((e.clientX-r.left)/step))});
  pc.addEventListener("keydown",e=>{if(e.key==="ArrowRight"||e.key==="ArrowUp"){e.preventDefault();setPointValue(v[i]+1)}else if(e.key==="ArrowLeft"||e.key==="ArrowDown"){e.preventDefault();setPointValue(v[i]-1)}else if(e.key==="Home"){e.preventDefault();setPointValue(0)}else if(e.key==="End"){e.preventDefault();setPointValue(10)}});
 });
}
function tier(s){
 const n=Number(s);if(!Number.isFinite(n))return["PENDIENTE","Evaluación no disponible"];
 if(n>=81)return["ALTA","Estimación estructural provisional"];
 if(n>=61)return["MEDIA-ALTA","Estimación estructural provisional"];
 if(n>=41)return["MEDIA","Estimación estructural provisional"];
 return["BAJA","Estimación estructural provisional"];
}
function radar(){
 const c=document.getElementById("radar"),x=c.getContext("2d"),w=c.width,h=c.height,cx=w/2,cy=h/2+3,r=91,n=10;x.clearRect(0,0,w,h);
 for(let q=1;q<=5;q++){x.beginPath();for(let i=0;i<n;i++){let a=-Math.PI/2+i*2*Math.PI/n,rr=r*q/5,X=cx+Math.cos(a)*rr,Y=cy+Math.sin(a)*rr;i?x.lineTo(X,Y):x.moveTo(X,Y)}x.closePath();x.strokeStyle="rgba(15,210,255,.23)";x.stroke()}
 for(let i=0;i<n;i++){let a=-Math.PI/2+i*2*Math.PI/n;x.beginPath();x.moveTo(cx,cy);x.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);x.strokeStyle="rgba(15,210,255,.22)";x.stroke()}
 x.beginPath();v.forEach((z,i)=>{let a=-Math.PI/2+i*2*Math.PI/n,rr=r*z/10,X=cx+Math.cos(a)*rr,Y=cy+Math.sin(a)*rr;i?x.lineTo(X,Y):x.moveTo(X,Y)});x.closePath();x.fillStyle="rgba(0,90,245,.38)";x.fill();x.strokeStyle="#ff26ef";x.lineWidth=3;x.shadowBlur=10;x.shadowColor="#b927ff";x.stroke();x.shadowBlur=0;
 x.fillStyle="#fff";x.font="bold 8px Arial";x.textAlign="center";v.forEach((z,i)=>{let a=-Math.PI/2+i*2*Math.PI/n; x.fillText(C[i][0].replace("POTENCIA OFENSIVA","POTENCIA"),cx+Math.cos(a)*(r+22),cy+Math.sin(a)*(r+22))});
}
function data(){return{name:document.getElementById("name").value,fmt,arch:document.getElementById("arch").value,date:document.getElementById("date").value,v:[...v],deckState:JSON.parse(JSON.stringify(deckState))}}
function share(){let u=location.href.split("#")[0]+"#deck="+btoa(unescape(encodeURIComponent(JSON.stringify(data()))));navigator.clipboard?.writeText(u);history.replaceState(null,"",u);toast("Enlace copiado.");}
function exportImage(){let c=document.createElement("canvas"),x=c.getContext("2d");c.width=1100;c.height=780;x.fillStyle="#020713";x.fillRect(0,0,1100,780);x.strokeStyle="#0bdcff";x.lineWidth=3;x.strokeRect(15,15,1070,750);x.textAlign="center";x.fillStyle="#fff";x.font="900 35px Arial";x.fillText("CALCULADORA DE BARAJAS",550,65);x.fillStyle="#ffe500";x.font="700 22px Arial";x.fillText(document.getElementById("name").value,550,100);let s=v.reduce((a,b)=>a+b,0),t=tier(s);x.fillStyle="#00eaff";x.font="900 70px Arial";x.fillText(s+" / 100",550,180);x.fillStyle="#ff26ef";x.font="900 34px Arial";x.fillText(t[0],550,225);x.fillStyle="#fff";x.font="700 18px Arial";x.fillText(t[1],550,255);x.textAlign="left";x.font="700 17px Arial";let y=310;C.forEach((c,i)=>{x.fillStyle="#fff";x.fillText(c[0],70,y);x.fillStyle="#00eaff";x.fillText(v[i]+"/10",480,y);x.fillStyle="#06224b";x.fillRect(540,y-14,460,14);x.fillStyle="#9d28ff";x.fillRect(540,y-14,46*v[i],14);y+=40});let a=document.createElement("a");a.download="analisis-baraja.png";a.href=c.toDataURL();a.click();toast("Imagen exportada.");}
function toast(s){let e=document.getElementById("toast");e.textContent=s;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2100)}
document.querySelectorAll(".fmt").forEach(b=>b.onclick=()=>{fmt=b.dataset.f;document.querySelectorAll(".fmt").forEach(x=>x.classList.toggle("active",x===b));const map={TCG:'tcg',OCG:'ocg','Master Duel':'master','Duel Links':'duelLinksSpeed','Duel Links RUSH':'duelLinksRush','Rush Duel':'rush','Speed Duel':'speedDuel',GOAT:'goat','Time Wizard':'timeWizard'};if(typeof selectBanFormat==='function'&&map[fmt]){try{selectBanFormat(map[fmt])}catch(e){}}try{comboLastAnalysis=[];renderComboDeckCards?.();renderComboLines?.()}catch(e){}});
document.getElementById("date").value=new Date().toISOString().slice(0,10);
makeStats();
